<script setup lang="ts">
import {computed,ref,watchPostEffect} from 'vue';import {ui} from '../state/device';import {t} from '../state/appearance';import type {Point} from '../contracts';
const figure=ref<HTMLElement|null>(null),rowHeight=ref(24.75);
watchPostEffect(cleanup=>{if(!ui.tasks.length)return;const row=figure.value?.parentElement?.querySelector('.task-table tbody tr');if(!row)return;const update=()=>{rowHeight.value=row.getBoundingClientRect().height;};const observer=new ResizeObserver(update);observer.observe(row);update();cleanup(()=>observer.disconnect());});
const capacity=computed(()=>ui.summary?.memory.find(pool=>pool.id==='internal')?.total_bytes??327680);
const end=computed(()=>Math.max(ui.cpu.at(-1)?.t??0,ui.memory.at(-1)?.t??0));
function line(points:Point[],maximum:number){return points.filter(point=>point.t>=end.value-60000).map((point,index)=>`${index?'L':'M'}${(4+(point.t-end.value+60000)/60000*752).toFixed(1)},${(55-Math.max(0,Math.min(maximum,point.value))/Math.max(1,maximum)*50).toFixed(1)}`).join(' ');}
const cpu=computed(()=>ui.coreCpu.length?ui.coreCpu.map((points,index)=>({label:ui.coreCpu.length>1?'CPU'+index:'CPU',path:line(points,100),color:index===0?'var(--lu-danger)':'var(--lu-primary)'})):[{label:'CPU',path:line(ui.cpu,100),color:'var(--lu-danger)'}]),memory=computed(()=>line(ui.memory,capacity.value/1024));
const label=computed(()=>t('CPU: загрузка 0–100%; MEM: свободная RAM 0–100% ёмкости. Общие 60 секунд.','CPU: 0–100% load; MEM: free RAM, 0–100% capacity. Shared 60-second timeline.'));
</script>
<template><figure ref="figure" :style="{'--task-row-height':rowHeight+'px'}" class="task-history" data-testid="task-history" :data-tooltip="label"><figcaption><span v-for="core in cpu" :key="core.label" :style="{color:core.color}">{{core.label}}</span><span class="task-history-memory">MEM</span></figcaption><svg viewBox="0 0 760 60" preserveAspectRatio="none" role="img" :aria-label="label" data-min="0" data-max="100"><g class="chart-grid"><path v-for="y in [5,17.5,30,42.5,55]" :key="y" :d="`M4 ${y}H756`" vector-effect="non-scaling-stroke"/><path v-for="x in [4,192,380,568,756]" :key="x" :d="`M${x} 5V55`" vector-effect="non-scaling-stroke"/></g><path v-for="core in cpu" :key="core.label" :d="core.path" :data-core="core.label" fill="none" :stroke="core.color" stroke-width="1.4" vector-effect="non-scaling-stroke"/><path :d="memory" class="task-history-memory" fill="none" stroke="currentColor" stroke-width="1.4" vector-effect="non-scaling-stroke"/></svg></figure></template>
